  if (display.textContent !== text) display.textContent = text;
  const hard = s.press > 0.6;
  const out = (hard ? "hard braking" : "brake released") + " · " + s.kw.toFixed(1) + " kW · " + (s.tripped ? "SDC open (latched)" : s.timer > 0 ? ms + " / 500 ms" : "SDC closed");
